<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { request, type Device, type Fault, type KnowledgeDoc, type AuditEvent } from '../api'
const loading=ref(true); const error=ref(''); const devices=ref<Device[]>([]); const faults=ref<Fault[]>([]); const docs=ref<KnowledgeDoc[]>([]); const audits=ref<AuditEvent[]>([]); const health=ref<any>(null)
const load=async()=>{loading.value=true;error.value='';try{[devices.value,faults.value,docs.value,audits.value,health.value]=await Promise.all([request<Device[]>('/devices'),request<Fault[]>('/fault-records'),request<KnowledgeDoc[]>('/knowledge/documents'),request<AuditEvent[]>('/audit-events'),request<any>('/health')])}catch(e){error.value=e instanceof Error?e.message:'无法加载运营数据'}finally{loading.value=false}}
onMounted(load)
</script>
<template><section class="page-view"><div class="page-heading"><div><span class="eyebrow">OPERATIONS OVERVIEW</span><h2>今天，现场发生了什么？</h2><p>从设备健康、故障处理到知识质量，查看当前组织的运行脉络。</p></div><button class="button secondary" @click="load" :disabled="loading">{{ loading?'刷新中…':'刷新数据' }}</button></div><p v-if="error" class="inline-error" role="alert">{{ error }} <button class="link-button" @click="load">重试</button></p><div v-if="loading" class="loading-state">正在加载运营数据…</div><template v-else><div class="metric-grid"><article class="metric-card"><span>授权设备</span><strong>{{ devices.length }}</strong><small>当前组织可见设备</small></article><article class="metric-card"><span>开放故障</span><strong>{{ faults.filter(x=>x.status!=='closed').length }}</strong><small>需要持续跟进</small></article><article class="metric-card"><span>已发布知识</span><strong>{{ docs.filter(x=>x.status==='published').length }}</strong><small>参与 RAG 检索</small></article><article class="metric-card"><span>服务状态</span><strong>{{ health?.status==='ok'?'正常':'检查' }}</strong><small>{{ audits.length }} 条近期审计事件</small></article></div><div class="dashboard-columns"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">FAULT QUEUE</span><h3>待处理故障</h3></div><RouterLink class="text-link" to="/faults">查看全部 →</RouterLink></div><div v-if="!faults.length" class="empty-panel">暂无故障记录，诊断结果确认后会出现在这里。</div><RouterLink v-for="fault in faults.slice(0,5)" :key="fault.id" :to="'/faults/'+fault.id" class="list-row"><span class="severity-dot" :class="'severity-'+fault.severity"></span><div><strong>{{ fault.symptom }}</strong><small>{{ fault.status }} · {{ new Date(fault.updated_at||fault.created_at).toLocaleString('zh-CN') }}</small></div><span>→</span></RouterLink></section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">KNOWLEDGE QUALITY</span><h3>知识库状态</h3></div><RouterLink class="text-link" to="/knowledge">管理 →</RouterLink></div><div v-for="doc in docs.slice(0,5)" :key="doc.id" class="list-row static-row"><span class="status-dot" :class="doc.status==='published'?'is-ok':''"></span><div><strong>{{ doc.name }}</strong><small>v{{ doc.version }} · {{ doc.status }} · {{ doc.chunks }} 段</small></div></div><div v-if="!docs.length" class="empty-panel">暂无知识文档。</div></section></div></template></section></template>